/**
 * LegalMind 娉曞緥宸ヤ綔鍙?- 涓诲伐浣滃彴缁勪欢
 * 鍩轰簬 Plait/Drawnix 寮€婧愮櫧鏉挎鏋舵瀯寤篭n * @see https://github.com/plait-board/drawnix
 * @see docs/TECHNICAL_STACK.md
 */

import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';

// ==================== Workspace Hooks瀵煎叆 ====================
// 浣跨敤閲嶆瀯鍚庣殑hooks杩涜鐘舵€佺鐞嗗拰鎿嶄綔
import {
  useWorkspaceState,
  useWorkspaceActions,
  useWorkspaceCanvas,
  useToolbarCallbacks,
  useAdditionalCallbacks,
  useKeyboardShortcutCallbacks,
} from './workspace/hooks';
import { createDemoNodes } from './workspace/utils';
import type { LegalNode } from './workspace/types';
export type { LegalNode };
import { PLAIT_OPTIONS, PLAIT_PLUGINS } from './workspace/config';

// ==================== Plait妗嗘灦鏍稿績瀵煎叆 ====================
// 杩欎簺鏄疨lait妗嗘灦鎻愪緵鐨勬牳蹇冨姛鑳絓nimport { MindThemeColors } from '@plait/mind';
import { PlaitBoardOptions, PlaitPlugin } from '@plait/core';

// ==================== 鑷畾涔夋彃浠跺鍏?====================
// 杩欐槸鎴戜滑涓烘硶寰嬩笟鍔″紑鍙戠殑鑷畾涔夋彃浠禱nimport { LegalNodeTypes } from '../plugins/legal-nodes/types';

// import { withLegalNodes } from '../plugins/legal-nodes/with-legal-nodes';  // 猸?娉曞緥鑺傜偣鎻掍欢
// ==================== UI缁勪欢瀵煎叆 ====================
// 鍩轰簬shadcn/ui鐨勫熀纭€UI缁勪欢锛屼笌LegalMind涓婚」鐩繚鎸佷竴鑷碶n// {{ AURA: Add - 瀵煎叆鑱婂ぉ璐村浘灞傜粍浠?}}
import { ChatNoteLayer } from './ChatNoteLayer';
import { Button } from './ui/button';// ==================== 鑷畾涔夌粍浠跺鍏?====================
// 杩欎簺鏄负娉曞緥涓氬姟寮€鍙戠殑鑷畾涔夌粍浠禱n
import { ViewSwitcher } from './ViewSwitcher';
import { LegalWorkflowTemplates } from './LegalWorkflowTemplates';
import { SaveTemplateDialog } from './SaveTemplateDialog';
import { useWorkspaceStore, WorkflowTemplate } from '../stores/workspaceStore';
// {{ AURA: Remove - 璇勮缁勪欢宸插湪CanvasRenderer涓覆鏌擄紝绉婚櫎瀵煎叆 }}

// ==================== 鎬ц兘浼樺寲瀵煎叆 ====================
// {{ AURA: Add - 闆嗘垚鎬ц兘浼樺寲妯″潡 }}
import { CanvasOptimizationManager } from '../lib/canvas-optimizations';
import { useAdvancedVirtualization } from '../hooks/useAdvancedVirtualization';
import { CanvasEmptyState } from './common/CanvasEmptyState';
import { v4 as uuidv4 } from 'uuid';



// ==================== 閫氱敤UI缁勪欢瀵煎叆 ====================
import {
  ModalPanel,
  AllModalsRenderer,
  ViewModeRenderer,
} from './common';
import { AIContextAwareness, AIContext } from './ai/AIContextAwareness';
import AISuggestionsFloatingPanel, { AISuggestion } from './common/AISuggestionsFloatingPanel';
import { VirtualCourtroomPanel } from './courtroom/VirtualCourtroomPanel'; // {{ AURA: Add - 鍙嫋鎷介潰鏉跨粍浠?}}
import { FloatingToolbar } from './FloatingToolbar'; // {{ AURA: Add - 鐢诲竷娴姩宸ュ叿鏍?}}
// {{ AURA: Add - AI Bailiff }}

import {
  calculateWorkspaceStats,
  generateNodeTypeTooltip,
  generateConnectionTypeTooltip,
  generateSelectedNodesTooltip,
  generateCollaboratorsTooltip,
} from './common/WorkspaceStats';

import { StatusBar } from './common/StatusBar';
import { AuxiliaryUIRenderer } from './common/AuxiliaryUIRenderer';
import { LegalRelationshipGraph } from './LegalRelationshipGraph';
import { PerformanceMonitor } from './common/PerformanceMonitor';
import { StatsPanel } from './common/StatsPanel';
import { DocumentPreview } from './common/DocumentPreview';
import { AutoSaveIndicator } from './common/AutoSaveIndicator';
import { NodeSearchPanel } from './NodeSearchPanel';
import { NodeFilterPanel } from './NodeFilterPanel';
import { ExportImportPanel } from './ExportImportPanel';
import { createDocumentNodeData } from '../types/document-node';
import type { DocumentNodeData } from '../types/document-node';
import { uploadFile, getFilesFromDragEvent } from '../lib/file-upload';
import { useAutoSave } from '../lib/auto-save'; // {{ AURA: Add - 鑷姩淇濆瓨Hook }}
import { useUndoRedo, useUndoRedoShortcuts } from '../lib/undo-redo'; // {{ AURA: Add - 鎾ら攢/閲嶅仛Hook }}

// {{ AURA: Add - 瀵煎叆鎼滅储寮曟搸鍜屽鍑?瀵煎叆鏈嶅姟 }}
import { SearchEngine } from '../lib/search-engine';


// ==================== 宸ュ叿鍑芥暟瀵煎叆 ====================
import { handleError, ErrorType, ErrorSeverity } from '../utils/errorHandler';
import { dataStorage } from '../utils/dataStorage';

import { useKeyboardShortcuts } from '../hooks/useKeyboardShortcuts';

import { KeyboardShortcutsPanel } from './common/KeyboardShortcutsPanel'; // {{ AURA: Add - 蹇嵎閿彁绀洪潰鏉?}}
import { Tutorial } from './Tutorial'; // {{ AURA: Add - 鏂版墜寮曞缁勪欢 }}
import { useTutorialStore, shouldShowTutorial } from '../stores/tutorialStore'; // {{ AURA: Add - 鏂版墜寮曞鐘舵€佺鐞?}}

// {{ AURA: Remove - 鍒犻櫎鏃х殑铏氭嫙鍖朒ook瀵煎叆锛屼娇鐢ㄦ柊鐨剈seAdvancedVirtualization }}
// import { useVirtualization, useConnectionVirtualization, useVirtualizationStats } from '../hooks/useVirtualization';
import { useResponsiveLayout } from '../hooks/useResponsiveLayout'; // {{ AURA: Add - 鍝嶅簲寮忓竷灞€Hook }}

// ==================== 浠茶涓撶敤鍔熻兘缁勪欢 ====================
// 杩欎簺缁勪欢鎻愪緵浠茶涓氬姟鐨勪笓鐢ㄥ姛鑳絓nimport { EvidenceChainVisualization } from './EvidenceChainVisualization';  // 璇佹嵁閾惧彲瑙嗗寲缁勪欢
import { LegalArticleCitation } from './LegalArticleCitation';  // 娉曞緥鏉℃枃寮曠敤缁勪欢

// ==================== AI鏅鸿兘鍔熻兘缁勪欢 ====================
// 杩欎簺缁勪欢鎻愪緵AI椹卞姩鐨勬櫤鑳藉垎鏋愬姛鑳斤紙褰撳墠涓烘帴鍙ｉ鐣欙紝鏈潵闆嗘垚鐪熷疄AI锛塡n// import { IntelligentNodeAnalyzer } from './ai/IntelligentNodeAnalyzer';              // 鏅鸿兘鑺傜偣鍒嗘瀽
// import { EvidenceRelationshipDetector } from './ai/EvidenceRelationshipDetector';    // 璇佹嵁鍏崇郴妫€娴媆n
// ==================== 鍗忎綔鍔熻兘缁勪欢 ====================
// 杩欎簺缁勪欢鎻愪緵澶氱敤鎴峰崗浣滃姛鑳斤紙鍩轰簬Plait鐨勫崗浣滆兘鍔涙墿灞曪級
// import { UserPermissionManager } from './collaboration/UserPermissionManager';        // 鐢ㄦ埛鏉冮檺绠＄悊

// import { MultiUserCollaboration } from './collaboration/MultiUserCollaboration'; // {{ AURA: Remove - 绉婚櫎鏃х殑鍗忎綔闈㈡澘 }}
import { FloatingCallWidget } from './collaboration/FloatingCallWidget'; // {{ AURA: Add - 鏂扮殑娴姩閫氳瘽缁勪欢 }}
import { Participant } from './collaboration/CollaborationControl'; // {{ AURA: Add - 鍙備笌鑰呯被鍨?}}
import { useCollaborationSync } from './workspace/hooks/useCollaborationSync'; // {{ AURA: Add - 鍗忎綔鍚屾Hook }}
import {
  Gavel,
  LayoutTemplate
} from 'lucide-react';
import type { DocumentMetadata } from './workspace/types';

// ==================== 鎺ュ彛瀹氫箟 ====================
export interface DrawnixLegalWorkspaceProps {
  initialData?: any; // Replace with specific type if available
  user?: {
    id: string;
    name: string;
    avatar: string;
  };
  participants?: Participant[];
  onStartCall?: (selectedIds: string[], type: 'video' | 'audio') => void;
  onEndCall?: () => void;
  onJoinCall?: () => void;
  isCallActive?: boolean;
  // Restored props
  caseId?: string;
  onStateChange?: (state: any) => void;
}

export const DrawnixLegalWorkspace: React.FC<DrawnixLegalWorkspaceProps> = ({
  initialData,

  participants: propParticipants,
  onStartCall,
  onEndCall,
  onJoinCall,
  isCallActive: propIsCallActive = false,
  // Restored props
  caseId,
  onStateChange
}) => {
  // ==================== 鐘舵€佺鐞?====================
  // ==================== 鍗忎綔鐘舵€?(Moved to props/internal default) ====================
  // 榛樿鍏抽棴
  const [isMuted, setIsMuted] = useState(false);
  const [isVideoOn, setIsVideoOn] = useState(true);
  const [isCallActive, setIsCallActive] = useState(propIsCallActive);

  // Sync prop state if provided
  useEffect(() => {
    if (typeof propIsCallActive !== 'undefined') {
      setIsCallActive(propIsCallActive);
    }
  }, [propIsCallActive]);

  // Mock participants if not provided
  const defaultParticipants: Participant[] = [
    { id: '1', name: '鏉庡緥甯?, avatar: 'https://i.pravatar.cc/150?u=1', status: 'online' },
    { id: '2', name: '寮犳硶鍔?, avatar: 'https://i.pravatar.cc/150?u=2', status: 'idle' },
    { id: '3', name: '鐜嬮【闂?, avatar: 'https://i.pravatar.cc/150?u=3', status: 'in-call' },
    { id: '4', name: '璧靛姪鐞?, avatar: 'https://i.pravatar.cc/150?u=4', status: 'offline' },
    { id: 'me', name: '鎴?, avatar: 'https://i.pravatar.cc/150?u=me', status: 'online' }
  ];

  const participants = propParticipants || defaultParticipants;

  // Default handlers if not provided
  // Default handlers if not provided
  const defaultStartCall = useCallback((selectedIds: string[], type: 'video' | 'audio') => {
    console.log(`Starting ${type} call with:`, selectedIds);
    setIsCallActive(true);
  }, []);
  const handleStartCall = onStartCall || defaultStartCall;

  const defaultEndCall = useCallback(() => {
    console.log('Ending call');
    setIsCallActive(false);
  }, []);
  const handleEndCall = onEndCall || defaultEndCall;

  const defaultJoinCall = useCallback(() => {
    console.log('Joining call');
    setIsCallActive(true);
  }, []);
  const handleJoinCall = onJoinCall || defaultJoinCall;


  // ==================== 娉ㄦ剰锛歝reateDemoNodes宸蹭粠./workspace/utils瀵煎叆 ====================
  // 涓嶉渶瑕佸湪杩欓噷閲嶅瀹氫箟

  // const DrawnixLegalWorkspaceComponent: React.FC<DrawnixLegalWorkspaceProps> = ({
  //   initialNodes = createDemoNodes(),
  //   onNodeCreate,
  //   onNodeUpdate,
  //   onNodeDelete,
  //   onAIAnalysis,
  //   caseId,
  //   onStateChange
  // }) => {


  // {{ AURA: Add - 鍚敤鍗忎綔鍚屾 }}
  useCollaborationSync();



  // {{ AURA: Add - AI涓婁笅鏂囩姸鎬?}}


  // {{ AURA: Add - 妗堜欢妯℃澘闈㈡澘鐘舵€?}}
  // ==================== 浣跨敤閲嶆瀯鍚庣殑Hooks ====================

  // 鐘舵€佺鐞咹ook
  // 鐘舵€佺鐞咹ook
  const {
    nodes,
    plaitElements, // {{ AURA: Add - Plait鍏冪礌 }}
    workspaceState,
    alignmentGuides,
    setNodes,
    setPlaitElements, // {{ AURA: Add - Plait鍏冪礌璁剧疆鍑芥暟 }}
    updateWorkspaceState,
    setAlignmentGuides,
    setSelectedNodes,
    togglePanel, // {{ AURA: Add - 鍒囨崲闈㈡澘鍑芥暟 }}
  } = useWorkspaceState(initialData?.nodes || createDemoNodes()); // Use initialData

  // {{ AURA: Remove - 璇勮绯荤粺鐘舵€佸凡鍦–anvasRenderer涓鐞?}}

  // 鎿嶄綔Hook
  const {
    createNode,
    handleNodeDoubleClick,
    handleNodeSave,
    handleNodeDelete,

    startConnection,
    handleNodeConnectionClick,
    cancelConnection,

    // {{ AURA: Add - 鎺ユ敹鍓创鏉挎搷浣?}}
    copyNodes,
    pasteNodes,
    cutNodes,
    performAIAnalysis,

  } = useWorkspaceActions(
    nodes,
    setNodes,
    workspaceState,
    updateWorkspaceState,
    // onNodeCreate, // These props are now part of the new DrawnixLegalWorkspaceProps
    // onNodeUpdate,
    // onNodeDelete,
    // onAIAnalysis
  );

  // {{ AURA: Fix - 绔嬪嵆鏇存柊鑺傜偣浣嶇疆锛岀Щ闄ゆ壒澶勭悊寤惰繜浠ユ秷闄ゆ嫋鎷藉欢杩熸劅 }}
  const handleBatchedNodePositionChange = useCallback((nodeId: string, position: { x: number; y: number }) => {
    // 鐩存帴鏇存柊锛屼笉浣跨敤鎵瑰鐞嗭紝鎻愪緵鍗虫椂瑙嗚鍙嶉
    setNodes(nodes.map(node =>
      node.id === nodeId
        ? { ...node, data: { ...node.data, position } }
        : node
    ));
  }, [nodes, setNodes]);

  // 鐢诲竷鎿嶄綔Hook
  const {
    canvasRef,
    handleZoomIn,
    handleZoomOut,
    handleResetView,
    handleFitToScreen,
    moveTo,
    getViewport,
  } = useWorkspaceCanvas(nodes);

  // {{ AURA: Add - 缁熻闈㈡澘鐘舵€佺鐞?}}
  const [showStatsPanel, setShowStatsPanel] = useState(false);

  // {{ AURA: Add - 鏂囨。棰勮鐘舵€佺鐞?}}
  const [previewingDocument, setPreviewingDocument] = useState<DocumentNodeData | null>(null);

  // {{ AURA: Add - 鎼滅储闈㈡澘鐘舵€佺鐞?}}
  const [showSearchPanel, setShowSearchPanel] = useState(false);
  const searchEngineRef = useRef(new SearchEngine());

  // {{ AURA: Add - 杩囨护闈㈡澘鐘舵€佺鐞?}}
  const [showFilterPanel, setShowFilterPanel] = useState(false);


  // {{ AURA: Add - 瀵煎嚭/瀵煎叆闈㈡澘鐘舵€佺鐞?}}
  const [showExportImportPanel, setShowExportImportPanel] = useState(false);
  const [showCourtroomPanel, setShowCourtroomPanel] = useState(false); // {{ AURA: Add - 铏氭嫙娉曞涵闈㈡澘鐘舵€?}}

  // {{ AURA: Add - AI Context State }}
  const [, setAiContext] = useState<AIContext | null>(null);
  const [aiSuggestions, setAiSuggestions] = useState<AISuggestion[]>([]);
  const [showAISuggestions, setShowAISuggestions] = useState(true);

  const handleContextUpdate = useCallback((context: AIContext) => {
    console.log('[AI] Context updated:', context);
    setAiContext(context);

    // Transform context insights into suggestions
    const newSuggestions: AISuggestion[] = [
      ...context.insights.map((text, i) => ({
        id: `insight-${i}`,
        text,
        type: 'analysis' as const,
        priority: 'medium' as const,
        confidence: 0.85
      })),
      ...context.suggestedActions.map((text, i) => ({
        id: `action-${i}`,
        text,
        type: 'node' as const,
        priority: 'high' as const,
        confidence: 0.92,
        onClick: () => console.log('Action clicked:', text)
      }))
    ];
    setAiSuggestions(newSuggestions);
    if (newSuggestions.length > 0) {
      setShowAISuggestions(true);
    }
  }, []);


  // {{ AURA: Add - 鎬ц兘鐩戞帶闈㈡澘鐘舵€佺鐞?}}
  // const [showPerformanceMonitor, setShowPerformanceMonitor] = useState(false);

  // {{ AURA: Add - 妗堜欢妯℃澘闈㈡澘鐘舵€佺鐞?}}
  const [showTemplatesPanel, setShowTemplatesPanel] = useState(false);
  const [showSaveTemplateDialog, setShowSaveTemplateDialog] = useState(false);

  // {{ AURA: Add - 鐢诲竷娴姩宸ュ叿鏍忕姸鎬佺鐞?}}
  const [floatingToolbarState, setFloatingToolbarState] = useState<{
    visible: boolean;
    position: { x: number; y: number } | null;
    canvasPosition: { x: number; y: number } | null;
  }>({
    visible: false,
    position: null,
    canvasPosition: null,
  });

  // {{ AURA: Add - 鑺傜偣绫诲瀷閫夋嫨鍣ㄧ姸鎬佺鐞?}}
  const [nodeSelectorState, setNodeSelectorState] = useState<{
    visible: boolean;
    position: { x: number; y: number } | null;
    canvasPosition: { x: number; y: number } | null;
  }>({
    visible: false,
    position: null,
    canvasPosition: null,
  });

  // {{ AURA: Add - 鎬ц兘浼樺寲绠＄悊鍣ㄥ垵濮嬪寲 }}
  const optimizationManagerRef = useRef<CanvasOptimizationManager | null>(null);


  // {{ AURA: Add - 楂樼骇铏氭嫙鍖朒ook }}
  const {
    visibleNodes,
    totalNodes,
    visibleCount,
    culledCount,
    cacheHitRate,
    performanceMetrics
  } = useAdvancedVirtualization(nodes, {
    viewport: getViewport(),
    canvasSize: { width: window.innerWidth, height: window.innerHeight }, // 绠€鍖栧鐞嗭紝瀹為檯搴旂洃鍚瑀esize
    enableCache: true,
    enableIncrementalUpdate: true,
    enableAdaptivePadding: true
  });

  // 鍒濆鍖栨€ц兘浼樺寲绠＄悊鍣╘n  useEffect(() => {
    if (!optimizationManagerRef.current) {
      optimizationManagerRef.current = new CanvasOptimizationManager({
        enableVirtualScroll: true,
        enableWorker: true,
        enablePerformanceMonitoring: true,
        virtualScrollOptions: {
          rootMargin: '200px',
          threshold: [0, 0.1, 0.5, 0.9, 1.0]
        },
        throttleOptions: {
          mousemove: 16, // 60fps
          scroll: 16,
          resize: 100
        },
        debounceOptions: {
          input: 300,
          search: 500
        }
      });

      console.log('[Performance] CanvasOptimizationManager initialized');
    }

    return () => {
      if (optimizationManagerRef.current) {
        optimizationManagerRef.current.destroy();
        optimizationManagerRef.current = null;
      }
    };
  }, []);

  // {{ AURA: Add - 鏂版墜寮曞鍒濆鍖?}}
  useEffect(() => {
    // 妫€鏌ユ槸鍚﹀簲璇ユ樉绀烘柊鎵嬪紩瀵糪n    if (shouldShowTutorial()) {
      const { startTutorial } = useTutorialStore.getState();
      // 寤惰繜1绉掓樉绀哄紩瀵硷紝纭繚椤甸潰宸插畬鍏ㄥ姞杞絓n      const timer = setTimeout(() => {
        startTutorial();
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, []);

  // {{ AURA: Add - 閲嶆柊鏌ョ湅寮曞鍥炶皟 }}
  const handleRestartTutorial = useCallback(() => {
    const { resetTutorial } = useTutorialStore.getState();
    resetTutorial();
  }, []);

  // {{ AURA: Add - 楂樼骇铏氭嫙鍖朒ook }}
  const viewport = useMemo(() => ({
    x: workspaceState.viewport.x,
    y: workspaceState.viewport.y,
    zoom: workspaceState.viewport.zoom
  }), [workspaceState.viewport]);

  const canvasSize = useMemo(() => ({
    width: typeof window !== 'undefined' ? window.innerWidth : 1920,
    height: typeof window !== 'undefined' ? window.innerHeight : 1080
  }), []);



  // {{ AURA: Add - 鎬ц兘鐩戞帶 }}
  useEffect(() => {
    if (performanceMetrics.totalTime > 50) {
      console.warn('[Performance] Slow virtualization:', performanceMetrics);
    }
  }, [performanceMetrics]);

  // {{ AURA: Add - 鍝嶅簲寮忓竷灞€Hook }}
  const {
    isMobile,
  } = useResponsiveLayout();

  // {{ AURA: Add - 鑷姩淇濆瓨鍔熻兘 }}
  const workspaceData = useMemo(() => ({
    nodes,
    connections: workspaceState.connections,
    viewport: getViewport(),
    timestamp: new Date().toISOString(),
  }), [nodes, workspaceState.connections, getViewport]);

  const autoSaveState = useAutoSave(workspaceData, {
    storageKey: caseId ? `workspace_${caseId}` : 'workspace_default',
    interval: 30000, // 30绉抃n    debounce: 1000, // 1绉抃n    maxHistory: 10,
    enabled: true,
    onSave: async (data) => {
      console.log('[AutoSave] Saving workspace data:', data);
      // 濡傛灉鎻愪緵浜唎nStateChange鍥炶皟锛屼篃璋冪敤瀹僜n      if (onStateChange) {
        onStateChange({
          nodes: data.nodes,
          connections: data.connections,
          viewport: data.viewport,
          metadata: { version: '1.0.0', editCount: 0 }, // Add metadata to satisfy CanvasState interface
        });
      }
    },
    onError: (error) => {
      console.error('[AutoSave] Failed to save:', error);
      handleError(error, ErrorType.STORAGE, ErrorSeverity.MEDIUM, 'AutoSave');
    },
  });

  // {{ AURA: Add - 鎾ら攢/閲嶅仛鍔熻兘 }}
  const undoRedoData = useMemo(() => ({
    nodes,
    connections: workspaceState.connections,
  }), [nodes, workspaceState.connections]);

  const {

    setState: setUndoRedoState,
    undo,
