 * 鎻愪緵鑷姩娓呯悊鍔熻兘锛岄槻姝㈠唴瀛樻硠婕廫n * 鍩轰簬2025骞碦eact鏈€浣冲疄璺礬n */

import * as React from 'react';
import { useEffect, useRef, useCallback } from 'react';

// ==================== 娓呯悊绠＄悊鍣?====================

/**
 * 娓呯悊鍑芥暟绫诲瀷
 */
export type CleanupFunction = () => void;

/**
 * 娓呯悊绠＄悊鍣ㄧ被
 * 闆嗕腑绠＄悊鎵€鏈夐渶瑕佹竻鐞嗙殑璧勬簮
 */
export class CleanupManager {
  private cleanups: Set<CleanupFunction> = new Set();
  private name: string;

  constructor(name: string = 'CleanupManager') {
    this.name = name;
  }

  /**
   * 娣诲姞娓呯悊鍑芥暟
   */
  add(cleanup: CleanupFunction): void {
    this.cleanups.add(cleanup);
  }

  /**
   * 绉婚櫎娓呯悊鍑芥暟
   */
  remove(cleanup: CleanupFunction): void {
    this.cleanups.delete(cleanup);
  }

  /**
   * 鎵ц鎵€鏈夋竻鐞嗗嚱鏁癨n   */
  cleanup(): void {
    console.log(`[${this.name}] Cleaning up ${this.cleanups.size} resources`);

    this.cleanups.forEach(cleanup => {
      try {
        cleanup();
      } catch (error) {
        console.error(`[${this.name}] Cleanup error:`, error);
      }
    });

    this.cleanups.clear();
  }

  /**
   * 鑾峰彇娓呯悊鍑芥暟鏁伴噺
   */
  get size(): number {
    return this.cleanups.size;
  }
}

// ==================== React Hooks ====================

/**
 * 浣跨敤娓呯悊绠＄悊鍣℉ook
 * 鑷姩鍦ㄧ粍浠跺嵏杞芥椂娓呯悊鎵€鏈夎祫婧怽n */
export function useCleanupManager(name?: string): CleanupManager {
  const managerRef = useRef<CleanupManager>();

  if (!managerRef.current) {
    managerRef.current = new CleanupManager(name || 'Component');
  }

  useEffect(() => {
    return () => {
      managerRef.current?.cleanup();
    };
  }, []);

  return managerRef.current;
}

/**
 * 浣跨敤瀹夊叏鐨勪簨浠剁洃鍚櫒Hook
 * 鑷姩鍦ㄧ粍浠跺嵏杞芥椂绉婚櫎鐩戝惉鍣╘n */
export function useSafeEventListener<K extends keyof WindowEventMap>(
  target: EventTarget | null | undefined,
  eventType: K,
  handler: (event: WindowEventMap[K]) => void,
  options?: AddEventListenerOptions
): void {
  const handlerRef = useRef(handler);
  handlerRef.current = handler;

  useEffect(() => {
    if (!target) return;

    const eventListener = (event: Event) => {
      handlerRef.current(event as WindowEventMap[K]);
    };

    target.addEventListener(eventType, eventListener, options);

    return () => {
      target.removeEventListener(eventType, eventListener, options);
    };

  }, [target, eventType, options?.capture, options?.passive, options?.once, options]);
}

/**
 * 浣跨敤瀹夊叏鐨勫畾鏃跺櫒Hook
 * 鑷姩鍦ㄧ粍浠跺嵏杞芥椂娓呴櫎瀹氭椂鍣╘n */
export function useSafeTimeout(
  callback: () => void,
  delay: number | null
): void {
  const callbackRef = useRef(callback);
  callbackRef.current = callback;

  useEffect(() => {
    if (delay === null) return;

    const timeout = setTimeout(() => {
      callbackRef.current();
    }, delay);

    return () => {
      clearTimeout(timeout);
    };
  }, [delay]);
}

/**
 * 浣跨敤瀹夊叏鐨勯棿闅斿畾鏃跺櫒Hook
 * 鑷姩鍦ㄧ粍浠跺嵏杞芥椂娓呴櫎瀹氭椂鍣╘n */
export function useSafeInterval(
  callback: () => void,
  delay: number | null
): void {
  const callbackRef = useRef(callback);
  callbackRef.current = callback;

  useEffect(() => {
    if (delay === null) return;

    const interval = setInterval(() => {
      callbackRef.current();
    }, delay);

    return () => {
      clearInterval(interval);
    };
  }, [delay]);
}

/**
 * 浣跨敤瀹夊叏鐨勫紓姝ユ搷浣淗ook
 * 闃叉鍦ㄧ粍浠跺嵏杞藉悗鏇存柊鐘舵€乗n */
export function useSafeAsync<T>(
  asyncFn: () => Promise<T>,
  deps: React.DependencyList = []
): {
  data: T | null;
  loading: boolean;
  error: Error | null;
  refetch: () => void;
} {
  const [data, setData] = React.useState<T | null>(null);
  const [loading, setLoading] = React.useState(false);
  const [error, setError] = React.useState<Error | null>(null);
  const isMountedRef = useRef(true);

  const execute = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const result = await asyncFn();
      if (isMountedRef.current) {
        setData(result);
      }
    } catch (err) {
      if (isMountedRef.current) {
        setError(err as Error);
      }
    } finally {
      if (isMountedRef.current) {
        setLoading(false);
      }
    }

  }, [asyncFn, ...deps]);

  useEffect(() => {
    execute();
  }, [execute]);

  useEffect(() => {
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  return { data, loading, error, refetch: execute };
}

/**
 * 浣跨敤瀹夊叏鐨凚lob URL Hook
 * 鑷姩鍦ㄧ粍浠跺嵏杞芥椂閲婃斁Blob URL
 */
export function useSafeBlobUrl(blob: Blob | null): string | null {
  const [url, setUrl] = React.useState<string | null>(null);

  useEffect(() => {
    if (!blob) {
      setUrl(null);
      return;
    }

    const blobUrl = URL.createObjectURL(blob);
    setUrl(blobUrl);

    return () => {
      URL.revokeObjectURL(blobUrl);
    };
  }, [blob]);

  return url;
}

/**
 * 浣跨敤瀹夊叏鐨勮闃匟ook
 * 鑷姩鍦ㄧ粍浠跺嵏杞芥椂鍙栨秷璁㈤槄
 */
export function useSafeSubscription<T>(
  subscribe: (callback: (value: T) => void) => () => void,
  deps: React.DependencyList = []
): T | null {
  const [value, setValue] = React.useState<T | null>(null);
  const isMountedRef = useRef(true);

  useEffect(() => {
    const unsubscribe = subscribe((newValue) => {
      if (isMountedRef.current) {
        setValue(newValue);
      }
    });

    return () => {
      unsubscribe();
    };

  }, [subscribe, ...deps]);

  useEffect(() => {
    return () => {
      isMountedRef.current = false;
    };
  }, []);

  return value;
}

